// ============================================================
// WEBHOOK: LARK INTERACTIVE Q&A
// Triggered when employee @mentions the bot in any Lark group
// ============================================================

const body = $input.first().json.body || $input.first().json;

// --- Handle Lark URL verification (first-time setup) ---
if (body.type === 'url_verification') {
  return [{ json: { action: 'verify', challenge: body.challenge } }];
}

// --- Parse message event ---
const event = body.event || body;
const chatId  = event.message?.chat_id || '';
const msgId   = event.message?.message_id || '';
const senderId = event.sender?.sender_id?.user_id || '';

// Extract text (Lark content is JSON string)
let rawText = '';
try {
  const content = JSON.parse(event.message?.content || '{}');
  rawText = content.text || content.content || '';
} catch (e) {
  rawText = String(event.message?.content || '');
}

// Remove @mention and clean up
const question = rawText.replace(/@[\w\u00C0-\u024F\u4e00-\u9fa5\u00C0-\u017E]+/gu, '').trim();

if (!question) {
  return [{ json: { action: 'skip', reason: 'empty question' } }];
}

// --- Detect which project the question is about ---
const projectMap = {
  XKMVN: { keywords: ['xkm', 'xịt', 'khử mùi', 'xkmvn'],         name: 'Xịt Khử Mùi VN',  sheet: 'XKMVN' },
  KTLVN: { keywords: ['ktl', 'ktlvn', 'ktl vn'],                   name: 'KTL Vietnam',       sheet: 'KTLVN' },
  TDCVN: { keywords: ['tdc', 'tdcvn'],                             name: 'TDC Vietnam',       sheet: 'TDCVN' },
  KTMVN: { keywords: ['ktmvn', 'ktm vn', 'ktm việt'],             name: 'KTM Vietnam',       sheet: 'KTMVN' },
  MNVN:  { keywords: ['mnvn', 'mn vn'],                            name: 'MN Vietnam',        sheet: 'MNVN'  },
  KTMR:  { keywords: ['ktmr', 'ktm market'],                       name: 'KTM Market',        sheet: 'KTMR'  },
  SRMR:  { keywords: ['srmr', 'sr market'],                        name: 'SR Market',         sheet: 'SRMR'  },
  KTLTL: { keywords: ['ktltl', 'ktl thai', 'thái', 'thailand'],   name: 'KTL Thailand',      sheet: 'KTLTL' },
  XKMTL: { keywords: ['xkmtl', 'xkm thai', 'xkm thái'],          name: 'XKM Thailand',      sheet: 'XKMTL' },
  XKMPH: { keywords: ['xkmph', 'philippines', 'phil', 'ph'],       name: 'XKM Philippines',   sheet: 'XKMPH' },
  XKMMY: { keywords: ['xkmmy', 'malaysia', 'malay', 'my'],        name: 'XKM Malaysia',      sheet: 'XKMMY' }
};

const lowerQ = question.toLowerCase();
let detectedProject = null;

for (const [id, cfg] of Object.entries(projectMap)) {
  if (cfg.keywords.some(kw => lowerQ.includes(kw))) {
    detectedProject = { id, ...cfg };
    break;
  }
}

// Default: use Tổng hợp sheet if no specific project detected
if (!detectedProject) {
  detectedProject = { id: 'TONG_HOP', name: 'Tổng hợp', sheet: 'Tổng hợp' };
}

return [{
  json: {
    action: 'reply',
    question,
    project: detectedProject,
    chatId,
    msgId,
    senderId
  }
}];

const parsedEvent = $('Parse Lark Event').first().json;
const sheetItems = $input.all();

const col = (item, idx) => {
  const obj = item.json || item;
  const keys = Object.keys(obj);
  return obj[keys[idx]];
};
const fmtSmart = (name, n) => {
  n = parseFloat(n) || 0;
  const isRatio = /tỷ lệ|margin|rate|cp\//i.test(name);
  if (isRatio) return (n*100).toFixed(1)+'%';
  if (Math.abs(n) >= 1e9) return (n/1e9).toFixed(2)+' tỷ';
  if (Math.abs(n) >= 1e6) return Math.round(n/1e6)+' tr';
  return n.toLocaleString('vi-VN');
};

const today = new Date();
const yesterdayColIdx = 5 + today.getDate() - 1;

// Build metric context from sheet
const contextData = {};
sheetItems.forEach(item => {
  const name = (col(item, 0) || '').toString().trim();
  if (!name || name.length < 3) return;
  const mtd  = parseFloat(col(item, 5)) || 0;
  const yday = parseFloat(col(item, yesterdayColIdx)) || 0;
  const bm   = (col(item, 1) || '').toString();
  if (mtd !== 0 || yday !== 0) {
    contextData[name] = {
      mtd:       fmtSmart(name, mtd),
      yesterday: fmtSmart(name, yday),
      benchmark: bm
    };
  }
});

const project = parsedEvent.project;
const question = parsedEvent.question;

const systemPrompt = `Bạn là AI phân tích kinh doanh của Hecatech, chuyên dự án ${project.name}.
Trả lời câu hỏi của nhân viên dựa trên data dashboard thực tế.
Viết tiếng Việt, súc tích, có số liệu cụ thể, đề xuất hành động khi cần.
Nếu câu hỏi ngoài phạm vi kinh doanh/data, từ chối lịch sự trong 1 câu.`;

const userPrompt = `Câu hỏi: "${question}"
Dự án: ${project.name}
Data hiện tại (MTD và hôm qua):
${JSON.stringify(contextData, null, 2)}

Trả lời ngắn gọn dưới 180 từ. Dẫn số liệu thực tế nếu liên quan.`;

return [{
  json: {
    parsedEvent,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 500,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];
